def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(value, default=(0, 0)):
        if isinstance(value, dict):
            x = value.get("x", default[0])
            y = value.get("y", default[1])
            return x, y
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return value[0], value[1]
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def best_step_toward(start, target):
        return [clamp_step(target[0] - start[0]), clamp_step(target[1] - start[1])]

    def iter_points(items):
        for item in items or []:
            yield pos(item)

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position", (0, 0)))
    ox, oy = pos(observation.get("opponent_position", (sx, sy)))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    grid_w = observation.get("grid_width", 0) or 0
    grid_h = observation.get("grid_height", 0) or 0
    center = ((grid_w - 1) / 2 if grid_w else sx, (grid_h - 1) / 2 if grid_h else sy)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return best_step_toward(self_pos, opp_pos)

        corners = [
            (0, 0),
            (0, max(0, grid_h - 1)),
            (max(0, grid_w - 1), 0),
            (max(0, grid_w - 1), max(0, grid_h - 1)),
        ]
        best = corners[0]
        best_score = None
        for c in corners:
            score = manhattan(c, opp_pos)
            if best_score is None or score > best_score:
                best_score = score
                best = c

        candidates = []
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                nx, ny = sx + dx, sy + dy
                score = manhattan((nx, ny), opp_pos) * 2 + manhattan((nx, ny), best) + manhattan((nx, ny), center) * 0.25
                candidates.append((score, dx, dy))
        candidates.sort(key=lambda t: (-t[0], abs(t[1]) + abs(t[2]), t[1], t[2]))
        return [candidates[0][1], candidates[0][2]]

    if env == "territory_control":
        targets = list(iter_points(observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier_cells") or []))
        if not targets:
            candidates = []
            for dx in (-1, 0, 1):
                for dy in (-1, 0, 1):
                    nx, ny = sx + dx, sy + dy
                    score = -manhattan((nx, ny), opp_pos) + manhattan((nx, ny), center) * 0.1
                    candidates.append((score, dx, dy))
