        return best_step_toward(self_pos, best)

    resources = list(iter_points(observation.get("resources") or observation.get("resource_cells") or []))
    if resources:
        best = min(resources, key=lambda p: (manhattan(p, self_pos), manhattan(p, opp_pos), p[0], p[1]))
        return best_step_toward(self_pos, best)

